int hidp_setup_hid_session(struct hidp_session *session, struct hidp_connadd_req *req)
{
	int ret = -ENOMEM;

	session->hid_dev = hid_allocate_device();
	if (!session->hid_dev)
		goto err_alloc_hid_dev;

	session->hid_dev->vendor = req->vendor;
	session->hid_dev->product = req->product;
	session->hid_dev->version = req->version;
	session->hid_dev->country = req->country;
	session->hid_dev->phys = kstrdup(req->phys, GFP_KERNEL);
	if (!session->hid_dev->phys)
		goto err_phys_strdup;

	session->hid_dev->driver = &hidp_hid_driver;

	ret = hid_parse_report(session->hid_dev, req->report_desc, req->report_desc_size);
	if (ret)
		goto err_report_parse;

	ret = hid_dev_register(session->hid_dev, &hidp_hid_driver);
	if (ret)
		goto err_dev_register;

	session->hid_dev->usage = req->usage;
	session->hid_dev->driver_data = session;

	if (hid_is_blacklisted(session->hid_dev)) {
		ret = -ENODEV;
		goto err_blacklisted;
	}

	return 0;

err_blacklisted:
	hid_dev_unregister(session->hid_dev);
err_dev_register:
err_report_parse:
	kfree(session->hid_dev->phys);
err_phys_strdup:
	hid_dev_free(session->hid_dev);
err_alloc_hid_dev:
	return ret;
}

int hidp_init_session(struct hidp_session *session, struct hidp_connadd_req *req)
{
	struct hid_device *hid;
	int err = -ENOMEM;

	hid = hid_allocate_device();
	if (IS_ERR(hid))
		return PTR_ERR(hid);

	session->hid = hid;
	session->input = NULL;

	hid->ll_driver = &hidp_hid_driver;
	hid->dev.parent = &session->hdev->dev;
	hid->vendor = req->vendor;
	hid->product = req->product;
	hid->version = req->version;
	hid->country = req->country;
	hid->phys = req->phys;

	err = hid_parse_report(hid, req->report_desc, req->report_desc_len);
	if (err)
		goto err_free_hid;

	err = hid_register_device(hid);
	if (err)
		goto err_free_hid;

	if (hid_is_blacklisted(hid)) {
		err = -ENODEV;
		goto err_unregister_hid;
	}

	return 0;

err_unregister_hid:
	hid_unregister_device(hid);
err_free_hid:
	hid_destroy_device(hid);
	return err;
}

int hidp_session_setup(struct hidp_session *session, struct hidp_connadd_req *req) {
    int err = -ENOMEM;

    session->hid_dev = hid_allocate_device();
    if (!session->hid_dev)
        return err;

    session->hid_dev->vendor = req->vendor;
    session->hid_dev->product = req->product;
    session->hid_dev->version = req->version;
    session->hid_dev->country = req->country;

    if (is_hid_blacklisted(session->hid_dev)) {
        hid_destroy_device(session->hid_dev);
        return -ENODEV;
    }

    session->hid_dev->driver = &hidp_driver;
    session->hid_dev->ll_driver = &hidp_ll_driver;

    err = hid_dev_set_input_report_length(session->hid_dev, req->input_report_length);
    if (err)
        goto err_out;

    err = hid_dev_set_output_report_length(session->hid_dev, req->output_report_length);
    if (err)
        goto err_out;

    session->hid_dev->usage = req->usage;
    session->hid_dev->usage_page = req->usage_page;
    session->hid_dev->phys = req->phys;

    err = hid_dev_register(session->hid_dev);
    if (err)
        goto err_out;

    return 0;

err_out:
    hid_destroy_device(session->hid_dev);
    return err;
}

int hidp_session_init(struct hidp_session *session, struct hidp_connadd_req *req) {
    int err;

    session->hid_dev = hid_allocate_device();
    if (!session->hid_dev) {
        return -ENOMEM;
    }

    session->hid_dev->vendor = req->vendor;
    session->hid_dev->product = req->product;
    session->hid_dev->version = req->version;
    session->hid_dev->country = req->country;

    if (hid_is_blacklisted(session->hid_dev)) {
        hid_destroy_device(session->hid_dev);
        return -ENODEV;
    }

    session->hid_dev->driver = hidp_hid_driver;
    session->hid_dev->dev.parent = &session->hdev->dev;

    err = hid_register_device(session->hid_dev);
    if (err) {
        hid_destroy_device(session->hid_dev);
        return err;
    }

    session->hid_dev->driver_data = session;
    return 0;
}

int hidp_setup_session(struct hidp_session *session, struct hidp_connadd_req *req)
{
    int ret = -ENOMEM;

    session->rd_data = kmalloc(req->rd_size, GFP_KERNEL);
    if (!session->rd_data)
        goto out;

    if (copy_from_user(session->rd_data, req->rd_data, req->rd_size))
        goto out_free;

    session->hid_dev = hid_allocate_device();
    if (!session->hid_dev)
        goto out_free;

    session->hid_dev->vendor = req->vendor;
    session->hid_dev->product = req->product;
    session->hid_dev->version = req->version;
    session->hid_dev->country = req->country;
    session->hid_dev->phys = req->phys;
    session->hid_dev->driver = &hidp_driver;

    if (hid_is_blacklisted(req->vendor, req->product)) {
        ret = -EPERM;
        goto out_free_dev;
    }

    ret = hid_register_device(session->hid_dev);
    if (ret)
        goto out_free_dev;

    session->connected = true;
    return 0;

out_free_dev:
    hid_free_device(session->hid_dev);
out_free:
    kfree(session->rd_data);
out:
    return ret;
}
